import sys

d = sys.stdin.read().split()
n = int(d[0])
M = int(d[1])
A = [int(x) for x in d[2:2 + n]]

def digits(x):
    r = []
    while True:
        r.append(x % 10)
        x //= 10
        if x == 0:
            break
    return r

md = digits(M)
low = min(md)
cnt = 0
for a in A:
    ad = digits(a)
    ok = True
    for x in ad:
        for y in md:
            if x == y:
                ok = False
    if ok and sum(ad) > low:
        cnt += 1
print(cnt)

